insert into xpms.dim_act (act_code, ordinal, definition) values
  ('PLAN', 1, 'Everything before money is committed: what it is, what it costs, and who has agreed to it.'),
  ('BUILD', 2, 'Money committed and the thing made real: awarded, fabricated, delivered, installed, commissioned.'),
  ('SHOW', 3, 'Doors open and everything downstream of doors: the run, the strike, the amplification, the reconciliation.');
insert into xpms.dim_phase (phase_code, gate, phase, act_code, definition, gate_exit, is_redefined) values
  ('SCP', 1, 'Scope', 'PLAN', 'What needs to happen. Brief intake, feasibility, budget envelope, objectives, jurisdiction, concept, development, engineering and scope lock. Absorbs the former Discover and Design.', 'Go or no-go ratified; budget envelope approved; objectives recorded; jurisdiction resolved; scope locked; spec drawings and sample approvals complete.', false),
  ('ENG', 2, 'Engage', 'PLAN', 'Who is going to make it happen. Every requirement in the locked scope carries a named accountable party: contracts executed, vendors awarded, talent booked, crew recruited, engagement agreements signed.', 'Contracts executed; every requirement in scope carries a named accountable party. An unassigned requirement is a gap under the silence rule, not a pass.', false),
  ('ADV', 3, 'Advance', 'PLAN', 'What they need to make it happen. Permits filed, insurance bound, riders and technical requirements reconciled against venue capability, rigging documented, PO baseline set. Advance in the production sense of the word.', 'Permits filed; no unresolved critical gaps between requirements and capability; no stale documents; rigging points and loads on file; PO baseline set.', true),
  ('PRC', 4, 'Procure', 'BUILD', 'Vendor award, deposits, long-lead orders, rate-card lock, submittals.', 'All awards issued; deposits paid; long-lead orders confirmed.', false),
  ('BLD', 5, 'Build', 'BUILD', 'Fabrication plus construction; shop QC.', 'Fabrication complete; QC passed; punch list opened.', false),
  ('INS', 6, 'Install', 'BUILD', 'Logistics, install, commissioning, punch closure.', 'Installed, commissioned, punch list closed; as-builts filed.', false),
  ('OPR', 7, 'Operate', 'SHOW', 'Run plus strike; live operations, dispatch, incident and daily reporting.', 'Show closed; strike complete; operating acceptance signed.', false),
  ('AMP', 8, 'Amplify', 'SHOW', 'Content capture, media and press, broadcast and livestream delivery, social amplification, post-event campaigns.', 'Capture assets delivered and archived; media distribution complete; broadcast masters delivered; post-event campaigns launched or handed off.', false),
  ('CLS', 9, 'Close', 'SHOW', 'Reconciliation and final cost report; archive handover.', 'Reconciled; final cost report filed; archive handed over.', false);
insert into xpms.dim_gate_criterion (criterion_id, gate, ordinal, statement, is_blocking) values
  ('G1.BUDGET_ENVELOPE', 1, 1, 'A budget envelope exists and is approved.', true),
  ('G1.GONOGO', 1, 2, 'Go / no-go decision ratified by a named party.', true),
  ('G1.OBJECTIVES_STATED', 1, 3, 'Measurable objectives recorded. Gate 8 measures against these.', false),
  ('G1.JURISDICTION', 1, 4, 'The project jurisdiction is resolved and populated. Without it no compliance rule can be evaluated at any later gate.', true),
  ('G1.SCOPE_LOCK', 1, 5, 'Scope locked; spec drawings and sample approvals complete.', true),
  ('G1.AMPLIFY_PLANNED', 1, 6, 'Capture, rights and measurement requirements for gate 8 are specified. Amplification cannot be retrofitted.', false),
  ('G1.CAPABILITY_FROZEN', 1, 7, 'Venue capability documents are frozen. A capability record still being edited cannot be reconciled against.', false),
  ('G2.CONTRACTS', 2, 8, 'Contracts executed; vendors awarded; talent booked; crew recruited.', true),
  ('G2.ACCOUNTABLE_PARTY', 2, 9, 'Every requirement in the locked scope carries a named accountable party. An unassigned requirement is a gap, not a pass.', true),
  ('G3.PERMITS_FILED', 3, 10, 'Every permit the jurisdiction requires is filed with lead time in hand.', true),
  ('G3.NO_CRITICAL_GAPS', 3, 11, 'Reconciliation of every requirement against its capability document leaves zero unresolved critical gaps. An UNKNOWN against a critical requirement counts as a gap.', true),
  ('G3.NO_STALE_DOCS', 3, 12, 'No requirement or capability document in the advance set is past its validity window.', true),
  ('G3.RIGGING_DOCUMENTED', 3, 13, 'Where a rigging requirement exists, the venue has a documented point and total load on file. Undocumented capacity is a hard stop.', true),
  ('G3.PO_BASELINE', 3, 14, 'PO baseline set; gate 9 reconciles against it.', true),
  ('G4.AWARDS', 4, 15, 'All awards issued; deposits paid; long-lead orders confirmed.', true),
  ('G4.UNITS_RESOLVED', 4, 16, 'Every awarded line carries a resolved unit. An unresolved unit refuses arithmetic rather than guessing.', true),
  ('G4.BAND_FRESHNESS', 4, 17, 'No award rests on a price band whose effective confidence has decayed to EXPIRED.', false),
  ('G5.FAB_QC', 5, 18, 'Fabrication complete; QC passed; punch list opened.', true),
  ('G5.ENGINEERING_STAMPED', 5, 19, 'Any load-bearing or occupied structure carries stamped engineering for its jurisdiction. An unstamped structure has no capacity anyone will stand behind.', true),
  ('G5.MATERIALS_TRACEABLE', 5, 20, 'Materials received against purchase orders with variance resolved.', false),
  ('G6.COMMISSIONED', 6, 21, 'Installed, commissioned, punch list closed; as-builts filed.', true),
  ('G6.AHJ_SIGNOFF', 6, 22, 'Every permit required by the jurisdiction is inspected and signed off. No rules for an unpopulated jurisdiction means this cannot be evaluated, not that it passes.', true),
  ('G6.EGRESS_VERIFIED', 6, 23, 'Occupant load, egress width and path verified against the adopted code as built, not as drawn.', true),
  ('G7.ACCEPTANCE', 7, 24, 'Show closed; strike complete; operating acceptance signed.', true),
  ('G7.INCIDENTS_CLOSED', 7, 25, 'Every incident, injury and near-miss logged and dispositioned.', true),
  ('G7.CAPTURE_SECURED', 7, 26, 'Capture media offloaded, checksummed and backed up before strike.', true),
  ('G8.CAPTURE_DELIVERED', 8, 27, 'Capture assets delivered and archived; broadcast masters delivered; media distribution complete.', true),
  ('G8.RIGHTS_CLEARED', 8, 28, 'Every published asset has cleared usage rights. UNKNOWN clearance is a blocker; publishing is irreversible.', true),
  ('G8.SPONSOR_OBLIGATIONS', 8, 29, 'Contracted sponsor deliverables evidenced and the proof-of-performance report issued.', true),
  ('G8.MEASUREMENT_REPORTED', 8, 30, 'Audience, earned-media and sentiment measurement delivered against the objectives set at gate 1.', false),
  ('G8.ARCHIVE_LODGED', 8, 31, 'Master assets lodged in the archive of record with retention terms stated.', true),
  ('G9.RECONCILED', 9, 32, 'Financially reconciled; final cost report filed against the gate 3 baseline.', true),
  ('G9.ASSETS_RETURNED', 9, 33, 'Every unit-grain asset accounted for: returned, transferred or written off with a named approver.', true),
  ('G9.OBLIGATIONS_DISCHARGED', 9, 34, 'Permits closed out, bonds released, temporary structures removed, site restored to its documented pre-event state.', true),
  ('G9.USAGE_RECORDED', 9, 35, 'Element usage written to the usage record.', false);
