insert into xpms.dim_identifier_class (class, ordinal, issued_by, scope, is_mutable, rule, examples) values
  ('identifier', 1, 'external authority (GS1, manufacturer, government)', 'global', false, 'We record it, we validate it, we never mint it. An identifier is globally true or it is wrong.', 'gtin14, mpn, unspsc, gpc_brick, isbn, sscc'),
  ('code', 2, 'GHXSTSHIP or a tenant', 'org (or canon, for XPMS-issued codes)', true, 'Ours to define and ours to change under governance. A code is never globally unique and must never be published as though it were.', 'urid, element_id, asset_tag, legacy_handle, phase_code, dept_code, region_code, jurisdiction_id'),
  ('token', 3, 'derived from position or context', 'path-local', true, 'Meaningful only relative to its parent. Never a join key across contexts.', 'org_token, event_token, venue_token, zone_token');
